package com.lbos.commercecustomer.controller; import com.lbos.commercecustomer.dto.request.*;import com.lbos.commercecustomer.dto.response.*;import com.lbos.commercecustomer.service.*;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import java.time.OffsetDateTime;import java.util.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/v1/cart") public class CartController {private final CartService service;public CartController(CartService s){service=s;}private <T> ApiResponse<T> ok(HttpServletRequest r,String m,T d){return ApiResponse.of(Optional.ofNullable(r.getHeader("X-Correlation-Id")).orElse("not-provided"),m,d);}@GetMapping public ApiResponse<CartResponse> get(HttpServletRequest h){return ok(h,"Cart retrieved",service.get());}@PostMapping("/items") public ResponseEntity<ApiResponse<CartItemResponse>> add(@Valid @RequestBody CartItemRequest r,HttpServletRequest h){return ResponseEntity.status(201).body(ok(h,"Cart item added",service.add(r)));}@PatchMapping("/items/{id}") public ApiResponse<CartItemResponse> update(@PathVariable UUID id,@Valid @RequestBody CartItemRequest r,HttpServletRequest h){return ok(h,"Cart item updated",service.update(id,r));}@DeleteMapping("/items/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable UUID id){service.delete(id);}@DeleteMapping @ResponseStatus(HttpStatus.NO_CONTENT) public void clear(){service.clear();}@PostMapping("/validate") public ApiResponse<CartValidationResponse> validate(HttpServletRequest h){return ok(h,"Cart validated",service.validate());}@PostMapping("/items/{id}/move-to-wishlist") @ResponseStatus(HttpStatus.NO_CONTENT) public void move(@PathVariable UUID id){service.moveToWishlist(id);}@PostMapping("/serviceability-check") public ApiResponse<CartServiceabilityResponse> checkServiceability(@Valid @RequestBody CartServiceabilityRequest r,HttpServletRequest h){return ok(h,"Cart serviceability checked",service.checkServiceability(r.addressId()));}}